/**
 * BEACON Agent - Backend Execution Agent for Case Orchestrated Normalization
 *
 * Purpose: Validate SQL generated by MOANA against HBM models in core-app
 *
 * Pattern: Agent only handles Claude SDK validation, Worker handles MOANA API calls
 *
 * ## Lifecycle
 * 1. [BEACON_INIT] - Agent created with repository path or ID
 * 2. [BEACON_REPO_REGISTER] - Repository registered in repo registry
 * 3. [BEACON_VALIDATE_START] - Validation begins
 * 4. [BEACON_VALIDATE_COMPLETE] - Validation finishes
 */

import {
    runAgent,
    getAgentPrompt,
    registerRepoFromPath,
    registerCustomerWorkspace,
    BEACON_OUTPUT_SCHEMA,
    type AgentResult,
    type ProgressUpdate,
} from '../../claude-sdk/index.js';
import { createLogger } from '../../utils/index.js';
import type { EventEmitter } from 'events';

const logger = createLogger('beacon-agent');

/**
 * BEACON Agent validation result
 */
export interface BEACONValidationResult {
    success: boolean;

    // Validation results
    validationChecklist: {
        category: string;
        items: Array<{
            check: string;
            status: 'PASS' | 'FAIL' | 'WARNING' | 'NA';
            details: string;
        }>;
    }[];

    // Code validation
    validatedAgainst: {
        repository: string;
        models: string[];
        tablesFound: string[];
        columnsValidated: string[];
    };

    // Overall assessment
    riskLevel: 'LOW' | 'MEDIUM' | 'HIGH';
    decision: 'SAFE TO EXECUTE' | 'EXECUTE WITH CAUTION' | 'NEEDS REVIEW' | 'NOT SAFE';
    recommendations: string[];

    // Metrics
    metrics: {
        durationMs: number;
        toolCalls: number;
        tokensUsed?: { input: number; output: number };
        costUsd?: number;
    };

    error?: string;
}

/**
 * Options for BEACON agent
 */
export interface BEACONAgentOptions {
    repoId?: string;
    repositoryPath?: string;
    timeoutMs?: number;
    webhookUrl?: string;
    onProgress?: (message: string) => void;
    eventEmitter?: EventEmitter;
}

/**
 * BEACON Agent - Validates SQL against HBM models using Claude
 */
export class BEACONAgent {
    private options: BEACONAgentOptions;
    private repoId: string;
    private repoIds: string[] = [];
    private instanceId: string;

    constructor(options: BEACONAgentOptions) {
        this.instanceId = `beacon-${Date.now()}`;

        this.options = {
            timeoutMs: 20 * 60 * 1000, // 20 minutes default
            ...options,
        };

        const logContext = {
            instanceId: this.instanceId,
            hasRepoId: !!options.repoId,
            hasRepositoryPath: !!options.repositoryPath,
            timeoutMs: this.options.timeoutMs,
        };

        logger.debug(logContext, '[BEACON_INIT] Creating BEACONAgent instance');

        // Resolve repoId from either repoId or repositoryPath (same as DARCI)
        if (options.repoId) {
            this.repoId = options.repoId;
            this.repoIds = [options.repoId];

            logger.info({
                ...logContext,
                repoId: this.repoId,
            }, '[BEACON_REPO_DIRECT] Using provided repoId');
        } else if (options.repositoryPath) {
            // Check if this is a customer workspace with symlinks
            if (options.repositoryPath.includes('/tasks/')) {
                logger.debug({
                    ...logContext,
                    repositoryPath: options.repositoryPath,
                }, '[BEACON_WORKSPACE_REGISTER] Registering customer workspace');

                const result = registerCustomerWorkspace(options.repositoryPath);
                this.repoId = result.workspaceId;
                this.repoIds = result.repoIds.length > 0 ? result.repoIds : [result.workspaceId];

                logger.info({
                    ...logContext,
                    workspaceId: result.workspaceId,
                    repoIds: this.repoIds,
                    symlinkCount: result.repoIds.length,
                }, '[BEACON_WORKSPACE_REGISTERED] Customer workspace registered');
            } else {
                // Direct git repository
                logger.debug({
                    ...logContext,
                    repositoryPath: options.repositoryPath,
                }, '[BEACON_REPO_REGISTER] Registering direct repository');

                this.repoId = registerRepoFromPath(options.repositoryPath);
                this.repoIds = [this.repoId];

                logger.info({
                    ...logContext,
                    repoId: this.repoId,
                }, '[BEACON_REPO_REGISTERED] Direct repository registered');
            }
        } else {
            logger.error(logContext, '[BEACON_INIT_ERROR] Missing repoId or repositoryPath');
            throw new Error('BEACONAgent requires either repoId or repositoryPath');
        }
    }

    /**
     * Validate SQL generated by MOANA against HBM models
     * 
     * @param generatedSql - SQL generated by MOANA
     * @param fileInfo - Information about the source XLSX file
     * @param moanaContext - Additional context from MOANA (query ID, explanation)
     * @param jiraTicketKey - JIRA ticket key for context
     * @returns Validation result
     */
    async validate(
        generatedSql: string,
        fileInfo: { fileName: string; rowCount: number; headers: string[] },
        moanaContext: { queryId: string; explanation: string },
        jiraTicketKey: string
    ): Promise<BEACONValidationResult> {
        const taskId = `${this.instanceId}-${Date.now()}`;
        const startTime = Date.now();

        const logContext = {
            instanceId: this.instanceId,
            taskId,
            repoId: this.repoId,
            repoIds: this.repoIds,
            jiraTicket: jiraTicketKey,
            moanaQueryId: moanaContext.queryId,
        };

        logger.info({
            ...logContext,
            sqlLength: generatedSql.length,
            rowCount: fileInfo.rowCount,
            fileName: fileInfo.fileName,
        }, '[BEACON_VALIDATE_START] Starting SQL validation');

        // Build validation prompt
        const validationPrompt = `You are validating SQL generated by MOANA for bulk case updates.

JIRA Ticket: ${jiraTicketKey}
MOANA Query ID: ${moanaContext.queryId}
Source File: ${fileInfo.fileName}
Row Count: ${fileInfo.rowCount}
Headers: ${fileInfo.headers.join(', ')}

MOANA Explanation:
${moanaContext.explanation}

Generated SQL:
\`\`\`sql
${generatedSql}
\`\`\`

VALIDATION TASKS:
1. Verify all table names exist in core-app HBM models (src/main/java/com/mh/mmm/db/entity/**/*.hbm.xml)
2. Verify all column names match HBM model field mappings
3. Check that UPDATE statements have proper WHERE clauses (no mass updates)
4. Verify scope keys are present (client_id, lob_id, case_id, etc.)
5. Check for transaction safety (START TRANSACTION / COMMIT)
6. Validate data types and formats match HBM definitions
7. Check for potential SQL injection risks
8. Verify row count matches expected operations
9. Check for proper NULL handling
10. Validate foreign key relationships

Focus on HBM files in core-app:
- Look for <class name="..." table="..."> definitions
- Check <property name="..." column="..."> mappings
- Verify <id> and <many-to-one> relationships
- Check required fields and constraints

Provide a detailed validation checklist with PASS/FAIL/WARNING/NA for each category.`;

        // Build progress handler that emits events
        let progressCount = 0;
        const onProgress = (update: ProgressUpdate) => {
            progressCount++;

            if (this.options.onProgress) {
                const message = update.toolName
                    ? `Validating: ${update.toolName}`
                    : update.message ?? `Validating SQL... (${update.elapsed}ms)`;
                this.options.onProgress(message);
            }

            if (this.options.eventEmitter) {
                this.options.eventEmitter.emit('agent:progress', update);
            }

            // Log tool usage periodically
            if (update.toolName) {
                logger.debug({
                    ...logContext,
                    toolName: update.toolName,
                    progressCount,
                    elapsed: update.elapsed,
                }, '[BEACON_TOOL_USE] Agent using tool');
            }
        };

        try {
            logger.debug({
                ...logContext,
                systemPromptPreview: getAgentPrompt('beacon').substring(0, 100),
            }, '[BEACON_RUN_AGENT] Calling runAgent');

            const result = await runAgent({
                taskId,
                taskPrompt: validationPrompt,
                repoIds: this.repoIds,
                agentType: 'beacon',
                systemAppend: getAgentPrompt('beacon'),
                permissionLevel: 'code_exploration',
                webhookUrl: this.options.webhookUrl,
                timeoutMs: this.options.timeoutMs,
                onProgress,
                outputSchema: BEACON_OUTPUT_SCHEMA,
            });

            const durationMs = Date.now() - startTime;
            const mappedResult = this.mapResult(result, durationMs);

            if (result.success) {
                logger.info({
                    ...logContext,
                    durationMs,
                    toolCalls: result.metrics.toolCalls,
                    progressUpdates: progressCount,
                    riskLevel: mappedResult.riskLevel,
                    decision: mappedResult.decision,
                }, '[BEACON_VALIDATE_SUCCESS] SQL validation completed successfully');
            } else {
                logger.warn({
                    ...logContext,
                    durationMs,
                    error: result.error,
                }, '[BEACON_VALIDATE_FAILED] SQL validation failed');
            }

            return mappedResult;
        } catch (error) {
            const durationMs = Date.now() - startTime;
            const errorMessage = error instanceof Error ? error.message : 'Unknown error';

            logger.error({
                ...logContext,
                durationMs,
                errorMessage,
                errorStack: error instanceof Error ? error.stack : undefined,
            }, '[BEACON_VALIDATE_ERROR] Exception during SQL validation');

            return {
                success: false,
                validationChecklist: [],
                validatedAgainst: {
                    repository: 'core-app',
                    models: [],
                    tablesFound: [],
                    columnsValidated: [],
                },
                riskLevel: 'HIGH',
                decision: 'NOT SAFE',
                recommendations: ['Validation failed due to error', errorMessage],
                metrics: {
                    durationMs,
                    toolCalls: 0,
                },
                error: errorMessage,
            };
        }
    }

    /**
     * Map AgentResult to BEACONValidationResult
     */
    private mapResult(result: AgentResult, durationMs: number): BEACONValidationResult {
        const structured = result.structuredOutput as any;

        return {
            success: result.success,
            validationChecklist: structured?.validationChecklist || [],
            validatedAgainst: structured?.validatedAgainst || {
                repository: 'core-app',
                models: [],
                tablesFound: [],
                columnsValidated: [],
            },
            riskLevel: structured?.riskLevel || 'MEDIUM',
            decision: structured?.decision || 'NEEDS REVIEW',
            recommendations: structured?.recommendations || [],
            metrics: {
                durationMs,
                toolCalls: result.metrics.toolCalls,
                tokensUsed: result.metrics.tokensUsed,
                costUsd: result.metrics.costUsd,
            },
            error: result.error,
        };
    }
}
